import { test, expect, type Page } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { boot, settle } from './helpers/editor';

/* Issue #449 - the shelf disables, with the reason, every control the open
 * document's enforced protection would refuse; the engine's typed
 * `Protected` refusal + toast stays the backstop for the keyboard, never
 * the only signal of a toolbar button.
 *
 * The fixtures are generated by `format_docx::test_fixtures::
 * protected_text_docx` and pinned by `crates/format-docx/tests/protection.rs`
 * (regenerate with `NGE_UPDATE_E2E_FIXTURES=1 cargo test -p format-docx
 * --test protection`): three paragraphs under `readOnly`, `comments` and
 * `trackedChanges` protection; `forms_protected.docx` is the forms one.
 *
 * Opening the document goes through `__dispatch` (setup only); everything
 * asserted is the live shell: the toolbar's own DOM state and titles, and a
 * real click on the one control a mode leaves open (a comment under
 * comments-only protection). */

const fixture = (name: string) =>
    Array.from(readFileSync(fileURLToPath(new URL(`./fixtures/${name}`, import.meta.url))));

declare global {
    interface Window {
        __dispatch: (cmd: unknown) => Promise<any>;
    }
}

const pos = (block: number, offset: number) => ({
    path: { steps: [{ kind: 'BLOCK', idx: block }] },
    offset,
});

/** Open `name`, wait for its protection badge and park a selection on
 *  paragraph 0's first word (so selection-gated controls are ready). */
async function openProtected(page: Page, name: string, badge: string): Promise<void> {
    await boot(page);
    const loaded = await page.evaluate(
        async ({ arr, name }) =>
            window.__dispatch({
                type: 'OPEN_DOCUMENT',
                bytes: new Uint8Array(arr),
                format: 'docx',
                name,
            }),
        { arr: fixture(name), name },
    );
    expect(loaded.type).toBe('DOCUMENT_LOADED');
    const sel = await page.evaluate(
        ({ start, end }) =>
            window.__dispatch({ type: 'SET_SELECTION', range: { start, end }, caret: end }),
        { start: pos(0, 0), end: pos(0, 4) },
    );
    expect(sel.type).toBe('SELECTION_CHANGED');
    await expect(page.locator('.nge-protection')).toContainText(badge);
}

/* The four controls the issue names. */
const bold = (page: Page) => page.getByRole('button', { name: 'Bold', exact: true });
const sizeBox = (page: Page) => page.getByLabel('Font size (pt)');
const insertTable = (page: Page) => page.getByRole('button', { name: /^Insert \d+×\d+ table$/ });
const insertImage = (page: Page) => page.getByRole('button', { name: 'Insert image', exact: true });
const newComment = (page: Page) => page.getByRole('button', { name: 'New comment', exact: true });

/** Every enabled control of the toolbar rows and the status bar, by its
 *  accessible name (aria-label, else its text). */
async function enabledControls(page: Page): Promise<string[]> {
    return page.evaluate(() => {
        const roots = document.querySelectorAll<HTMLElement>(
            '.nge-shell__topbar, .nge-shell__statusbar',
        );
        const names: string[] = [];
        for (const root of roots) {
            for (const el of root.querySelectorAll<HTMLElement>(
                'button, select, input:not([type="file"])',
            )) {
                if ((el as HTMLButtonElement).disabled) continue;
                if (el.getAttribute('aria-disabled') === 'true') continue;
                const name =
                    el.getAttribute('aria-label') ||
                    (el.textContent ?? '').trim() ||
                    el.getAttribute('title') ||
                    el.tagName;
                names.push(name);
            }
        }
        return names.sort();
    });
}

const REASON_READ_ONLY = 'Not available: this document is protected (read-only)';

test('an unprotected document leaves the controls enabled (the baseline)', async ({ page }) => {
    test.setTimeout(45_000);
    await boot(page);
    await page.evaluate(() => window.__dispatch({ type: 'SELECT_ALL' }));
    await expect(page.locator('.nge-protection')).toHaveCount(0);
    for (const control of [bold(page), sizeBox(page), insertTable(page), insertImage(page), newComment(page)]) {
        await expect(control).toBeEnabled();
    }
    await expect(bold(page)).toHaveAttribute('title', 'Bold (Ctrl+B)');
});

test('read-only: Bold, the size box, Insert Table and Insert Image are disabled with the reason', async ({
    page,
}) => {
    test.setTimeout(60_000);
    await openProtected(page, 'readonly_protected.docx', 'Read-only');

    await expect(bold(page)).toBeDisabled();
    await expect(bold(page)).toHaveAttribute('title', REASON_READ_ONLY);
    await expect(sizeBox(page)).toBeDisabled();
    await expect(sizeBox(page)).toHaveAttribute('title', REASON_READ_ONLY);
    await expect(insertTable(page)).toBeDisabled();
    await expect(insertTable(page)).toHaveAttribute('title', REASON_READ_ONLY);
    await expect(insertImage(page)).toBeDisabled();
    await expect(insertImage(page)).toHaveAttribute('title', REASON_READ_ONLY);
    /* Read-only refuses comments too. */
    await expect(newComment(page)).toBeDisabled();
    await expect(newComment(page)).toHaveAttribute('title', REASON_READ_ONLY);

    /* Nothing was dispatched, so nothing was refused. */
    await settle(page);
    await expect(page.locator('.nge-toast__message')).toHaveCount(0);
});

test('read-only: no control is left enabled that only produces a refusal', async ({ page }) => {
    test.setTimeout(60_000);
    await openProtected(page, 'readonly_protected.docx', 'Read-only');
    await settle(page);
    const enabled = await enabledControls(page);
    /* What a read-only document still lets the user do: open / save /
       export, look at a header or footer (entering a band is exempt - the
       edits in it are refused), toggle the field-code VIEW, zoom and the
       renderer / settings menu. Anything else enabled here would answer a
       click with a `Protected` toast. */
    const allowed = [
        /^File/,
        /^Edit header$/,
        /^Edit footer$/,
        /Field$/,
        /Codes$/,
        /zoom/i,
        /Fit page width/,
        /^Settings/,
    ];
    const surprising = enabled.filter((name) => !allowed.some((re) => re.test(name)));
    expect(surprising, `enabled under read-only protection: ${surprising.join(', ')}`).toEqual([]);
});

test('comments-only: the comment button stays enabled and takes a comment; the rest is locked', async ({
    page,
}) => {
    test.setTimeout(60_000);
    await openProtected(page, 'comments_protected.docx', 'Comments only');

    await expect(bold(page)).toBeDisabled();
    await expect(bold(page)).toHaveAttribute(
        'title',
        'Not available: this document is protected (comments only)',
    );
    await expect(sizeBox(page)).toBeDisabled();
    await expect(insertTable(page)).toBeDisabled();
    await expect(insertImage(page)).toBeDisabled();
    await expect(newComment(page)).toBeEnabled();
    await expect(newComment(page)).toHaveAttribute('title', 'New comment on selected range');

    /* A real comment goes through the real controls. */
    await newComment(page).click();
    const draft = page.getByRole('dialog', { name: 'New comment' });
    await draft.getByPlaceholder('Comment text…').fill('Looks good');
    await draft.getByRole('button', { name: 'Comment', exact: true }).click();
    await expect(page.locator('.nge-cm__count')).toHaveText('1');
    await expect(page.locator('.nge-cm__card').first()).toContainText('Looks good');
    /* The reply / resolve / delete actions of the rail are comment-class
       commands: open under comments-only protection. */
    await expect(page.getByRole('button', { name: 'Resolve comment' })).toBeEnabled();
    await expect(page.getByRole('button', { name: 'Reply to comment' })).toBeEnabled();
    await expect(page.locator('.nge-toast__message')).toHaveCount(0);
});

test('tracked-changes: formatting and comments stay enabled, structure is locked', async ({
    page,
}) => {
    test.setTimeout(60_000);
    await openProtected(page, 'tracked_protected.docx', 'Tracked changes only');

    await expect(bold(page)).toBeEnabled();
    await expect(sizeBox(page)).toBeEnabled();
    await expect(newComment(page)).toBeEnabled();
    await expect(insertTable(page)).toBeDisabled();
    await expect(insertTable(page)).toHaveAttribute(
        'title',
        'Not available: this document is protected (tracked changes only)',
    );
    await expect(insertImage(page)).toBeDisabled();
    /* Review mode is forced on: the Track toggle is locked, with its own reason. */
    await expect(page.getByRole('button', { name: 'Track changes' })).toBeDisabled();
    await expect(page.getByRole('button', { name: 'Track changes' })).toHaveAttribute(
        'title',
        /required by this document/,
    );
});

test('tracked-changes: inside a header every edit control locks (stories are never recorded)', async ({
    page,
}) => {
    test.setTimeout(60_000);
    await openProtected(page, 'tracked_protected.docx', 'Tracked changes only');
    await expect(bold(page)).toBeEnabled();

    /* Entering a band is exempt from protection (looking is allowed). */
    await page.getByRole('button', { name: 'Edit header', exact: true }).click();
    await expect(page.getByRole('button', { name: 'Close header/footer editing' })).toBeVisible();

    await expect(bold(page)).toBeDisabled();
    await expect(bold(page)).toHaveAttribute(
        'title',
        'Not available: headers, footers, notes and text boxes cannot be edited in a protected document (tracked changes only)',
    );
    await expect(sizeBox(page)).toBeDisabled();
    await expect(newComment(page)).toBeDisabled();

    /* Closing the band hands the controls back. */
    await page.getByRole('button', { name: 'Close header/footer editing' }).click();
    await expect(bold(page)).toBeEnabled();
    await expect(page.locator('.nge-toast__message')).toHaveCount(0);
});

test('forms: formatting, structure and comments are locked', async ({ page }) => {
    test.setTimeout(60_000);
    await openProtected(page, 'forms_protected.docx', 'Filling in forms');
    for (const control of [bold(page), sizeBox(page), insertTable(page), insertImage(page), newComment(page)]) {
        await expect(control).toBeDisabled();
        await expect(control).toHaveAttribute(
            'title',
            /^Not available: this document is protected \(filling in forms\)$/,
        );
    }
});

test('opening an unprotected document lifts the locks again', async ({ page }) => {
    test.setTimeout(60_000);
    await openProtected(page, 'readonly_protected.docx', 'Read-only');
    await expect(bold(page)).toBeDisabled();
    await page.evaluate(() => window.__dispatch({ type: 'CLOSE_DOCUMENT' }));
    await page.evaluate(() => window.__dispatch({ type: 'SELECT_ALL' }));
    await expect(page.locator('.nge-protection')).toHaveCount(0);
    await expect(bold(page)).toBeEnabled();
    await expect(insertTable(page)).toBeEnabled();
});
